package com.caroulette.export;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(CaRouletteExportConfig.GROUP)
public interface CaRouletteExportConfig extends Config
{
	String GROUP = "caRouletteExport";

	@ConfigItem(
		keyName = "includeDescriptions",
		name = "Include CA descriptions",
		description = "Write the description text of every combat achievement into the export file.",
		position = 1
	)
	default boolean includeDescriptions()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeItems",
		name = "Include items (worn + inventory)",
		description = "Write your equipped and inventory items into the export. Used by the website's \"can I attempt this\" filter.",
		position = 2
	)
	default boolean includeItems()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeBank",
		name = "Include bank (if open)",
		description = "Also write your bank contents, but only if the bank was opened at least once this session.",
		position = 3
	)
	default boolean includeBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "printFilePath",
		name = "Print file path in chat",
		description = "After exporting, print the full path of the written file as a game message.",
		position = 4
	)
	default boolean printFilePath()
	{
		return true;
	}
}

