package com.caroulette.export;

import java.awt.BorderLayout;
import java.awt.Font;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.PluginPanel;

class CaRouletteExportPanel extends PluginPanel
{
	/**
	 * Swing only wraps an HTML label if it is given an explicit width, so the body
	 * width is pinned to the usable panel width (PANEL_WIDTH minus our own border).
	 */
	private static final int TEXT_WIDTH = PluginPanel.PANEL_WIDTH - 30;

	private final JLabel status = new JLabel(wrap("Not exported yet."));

	CaRouletteExportPanel(Runnable onExport)
	{
		super(false);
		setLayout(new BorderLayout(0, 10));
		setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));

		final JLabel title = new JLabel("CA Roulette Export");
		title.setFont(title.getFont().deriveFont(Font.BOLD, 15f));

		final JLabel blurb = new JLabel(wrap("Writes your Combat Achievements, skills, quests and items to"
			+ " <code>.runelite/ca-roulette/&lt;name&gt;.json</code>. Upload that file to the CA Roulette site."
			+ "<br><br>You can also run <code>::caexport</code> in the chat box."));

		final JButton export = new JButton("Export my data");
		export.addActionListener(e -> onExport.run());

		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		status.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));

		// DynamicGridLayout keeps each row at its own preferred height, so the
		// button is not stretched to match the height of the description.
		final JPanel north = new JPanel(new DynamicGridLayout(0, 1, 0, 8));
		north.add(title);
		north.add(blurb);
		north.add(export);

		add(north, BorderLayout.NORTH);
		add(status, BorderLayout.CENTER);
	}

	void setStatus(String text)
	{
		SwingUtilities.invokeLater(() -> status.setText(wrap(text)));
	}

	private static String wrap(String html)
	{
		return "<html><body style='width:" + TEXT_WIDTH + "px'>" + html + "</body></html>";
	}
}

