import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "CA Roulette Export",
	description = "Export your Combat Achievements, skills, quests and items to a JSON file",
	tags = {"combat", "achievements", "export", "json", "roulette", "ca"}
)
public class CaRouletteExportPlugin extends Plugin
{
	/** Chat command: {@code ::caexport} */
	private static final String COMMAND = "caexport";

	// Combat achievement tier -> the client Enum that lists that tier's task structs.
	// (CA-reading approach adapted from cdfisher/ca-export, BSD-2-Clause)
	private static final String[] TIER_NAMES = {"Easy", "Medium", "Hard", "Elite", "Master", "Grandmaster"};
	private static final int[] TIER_ENUM_IDS = {3981, 3982, 3983, 3984, 3985, 3986};
	private static final int[] TIER_POINTS = {1, 2, 3, 4, 5, 6};

	// Struct params on each combat-achievement task struct.
	private static final int PARAM_TASK_ID = 1306;
	private static final int PARAM_TASK_NAME = 1308;
	private static final int PARAM_TASK_DESC = 1309;

	// VarPlayers holding the completion bitfield: task N -> bit (N % 32) of VARP[N / 32].
	// 21 varps == 672 task slots. Append CA_TASK_COMPLETED_21+ here if the CA task count
	// ever exceeds that; until then, out-of-range ids are reported as not-completed.
	private static final int[] TASK_COMPLETED_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1, VarPlayerID.CA_TASK_COMPLETED_2,
		VarPlayerID.CA_TASK_COMPLETED_3, VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7, VarPlayerID.CA_TASK_COMPLETED_8,
		VarPlayerID.CA_TASK_COMPLETED_9, VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13, VarPlayerID.CA_TASK_COMPLETED_14,
		VarPlayerID.CA_TASK_COMPLETED_15, VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19, VarPlayerID.CA_TASK_COMPLETED_20,
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private CaRouletteExportConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	private NavigationButton navButton;
	private CaRouletteExportPanel panel;

	// Last-seen contents of the containers we care about, so an export still has
	// item data even on a game tick where the live container is momentarily null.
	private final Map<Integer, List<ExportData.Item>> containerCache = new ConcurrentHashMap<>();

	// Guards against overlapping exports (e.g. spamming ::caexport) writing the same file at once.
	private final AtomicBoolean exportInProgress = new AtomicBoolean();

	@Provides
	CaRouletteExportConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CaRouletteExportConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new CaRouletteExportPanel(() -> clientThread.invoke(() -> export("panel")));
		navButton = NavigationButton.builder()
			.tooltip("CA Roulette Export")
			.icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted commandExecuted)
	{
		if (commandExecuted.getCommand().equalsIgnoreCase(COMMAND))
		{
			export("command");
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		final GameState state = gameStateChanged.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			containerCache.clear();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		final int id = event.getContainerId();
		if (id == InventoryID.INV || id == InventoryID.WORN || id == InventoryID.BANK)
		{
			containerCache.put(id, snapshot(event.getItemContainer()));
		}
	}

	/**
	 * Gather everything off the client thread, then hand the finished object to a
	 * background thread for JSON serialisation + file IO.
	 */
	private void export(String trigger)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			status("Log in first, then export.");
			return;
		}

		final Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			status("Player not loaded yet - try again in a moment.");
			return;
		}

		if (!exportInProgress.compareAndSet(false, true))
		{
			status("An export is already in progress.");
			return;
		}

		final ExportData data;
		try
		{
			data = buildExport(local);
		}
		catch (Exception e)
		{
			exportInProgress.set(false);
			log.warn("CA Roulette Export: failed to gather data", e);
			status("Export failed while reading game data - see client log.");
			return;
		}

		executor.submit(() ->
		{
			try
			{
				writeFile(data, trigger);
			}
			finally
			{
				exportInProgress.set(false);
			}
		});
	}

	private ExportData buildExport(Player local)
	{
		final ExportData data = new ExportData();
		data.generatedAt = Instant.now().toString();
		data.username = local.getName();
		data.displayName = local.getName();
		data.combatLevel = local.getCombatLevel();
		data.accountType = accountType();

		final RuneScapeProfileType profile = RuneScapeProfileType.getCurrent(client);
		data.profileType = profile == RuneScapeProfileType.STANDARD ? "" : "-" + profile.name();

		// ---- skills (real / un-boosted) ----
		data.skills = new LinkedHashMap<>();
		for (Skill skill : Skill.values())
		{
			data.skills.put(skill.getName(), client.getRealSkillLevel(skill));
		}

		// ---- quests ----
		data.quests = new LinkedHashMap<>();
		data.questsFinished = new ArrayList<>();
		for (Quest quest : Quest.values())
		{
			final QuestState state = quest.getState(client);
			data.quests.put(quest.getName(), state.name());
			if (state == QuestState.FINISHED)
			{
				data.questsFinished.add(quest.getName());
			}
		}

		// ---- combat achievements ----
		data.combatAchievements = buildCombatAchievements();

		// ---- items ----
		data.items = buildItems();

		return data;
	}

	private ExportData.CombatAchievements buildCombatAchievements()
	{
		final ExportData.CombatAchievements ca = new ExportData.CombatAchievements();
		ca.tasks = new ArrayList<>();
		ca.completedIds = new ArrayList<>();
		ca.incompleteIds = new ArrayList<>();
		ca.tasksCompletedByTier = new LinkedHashMap<>();
		ca.tasksTotalByTier = new LinkedHashMap<>();

		final boolean withDesc = config.includeDescriptions();

		for (int t = 0; t < TIER_ENUM_IDS.length; t++)
		{
			final String tier = TIER_NAMES[t];
			final int tierPoints = TIER_POINTS[t];
			int tierDone = 0;
			int tierTotal = 0;

			final EnumComposition tierEnum = client.getEnum(TIER_ENUM_IDS[t]);
			if (tierEnum == null)
			{
				log.warn("CA Roulette Export: {} tier enum {} not found - its tasks will be missing",
					tier, TIER_ENUM_IDS[t]);
				continue;
			}

			for (int structId : tierEnum.getIntVals())
			{
				final StructComposition struct = client.getStructComposition(structId);
				if (struct == null)
				{
					continue;
				}

				final int id = struct.getIntValue(PARAM_TASK_ID);
				final String name = struct.getStringValue(PARAM_TASK_NAME);
				final boolean completed = isTaskCompleted(id);

				final ExportData.Task task = new ExportData.Task();
				task.id = id;
				task.name = name;
				task.description = withDesc ? struct.getStringValue(PARAM_TASK_DESC) : null;
				task.tier = tier;
				task.points = tierPoints;
				task.completed = completed;
				ca.tasks.add(task);

				tierTotal++;
				ca.tasksTotal++;
				ca.pointsTotal += tierPoints;
				if (completed)
				{
					tierDone++;
					ca.tasksCompleted++;
					ca.pointsEarned += tierPoints;
					ca.completedIds.add(id);
				}
				else
				{
					ca.incompleteIds.add(id);
				}
			}

			ca.tasksCompletedByTier.put(tier, tierDone);
			ca.tasksTotalByTier.put(tier, tierTotal);
		}

		if (ca.tasksTotal == 0)
		{
			log.warn("CA Roulette Export: read 0 combat achievement tasks - the tier enum ids may have changed");
		}

		return ca;
	}

	private boolean isTaskCompleted(int taskId)
	{
		final int index = taskId >>> 5;   // taskId / 32
		final int bit = taskId & 31;      // taskId % 32
		if (index < 0 || index >= TASK_COMPLETED_VARPS.length)
		{
			return false;
		}
		return (client.getVarpValue(TASK_COMPLETED_VARPS[index]) & (1 << bit)) != 0;
	}

	private ExportData.Items buildItems()
	{
		final ExportData.Items items = new ExportData.Items();
		if (config.includeItems())
		{
			// A logged-in player whose worn/inventory container is null simply has it
			// empty (RuneLite doesn't materialise an empty container until it changes),
			// so coalesce null -> [] rather than reporting "unknown".
			final List<ExportData.Item> equipment = readContainer(InventoryID.WORN);
			final List<ExportData.Item> inventory = readContainer(InventoryID.INV);
			items.equipment = equipment != null ? equipment : new ArrayList<>();
			items.inventory = inventory != null ? inventory : new ArrayList<>();
		}
		if (config.includeBank())
		{
			final List<ExportData.Item> bank = readContainer(InventoryID.BANK);
			if (bank != null && !bank.isEmpty())
			{
				items.bank = bank;
				items.bankIncluded = true;
			}
			else
			{
				items.note = "Bank not captured - open your bank once this session before exporting to include it.";
			}
		}
		return items;
	}

	/** Live container if present, otherwise the last snapshot we cached from an event. */
	private List<ExportData.Item> readContainer(int inventoryId)
	{
		final ItemContainer container = client.getItemContainer(inventoryId);
		if (container != null)
		{
			return snapshot(container);
		}
		return containerCache.get(inventoryId);
	}

	private List<ExportData.Item> snapshot(ItemContainer container)
	{
		if (container == null)
		{
			return null;
		}
		final List<ExportData.Item> out = new ArrayList<>();
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			String name;
			try
			{
				name = itemManager.getItemComposition(item.getId()).getName();
			}
			catch (RuntimeException e)
			{
				name = null;
			}
			out.add(new ExportData.Item(item.getId(), name, item.getQuantity()));
		}
		return out;
	}

	private String accountType()
	{
		switch (client.getVarbitValue(VarbitID.IRONMAN))
		{
			case 1:
				return "IRONMAN";
			case 2:
				return "ULTIMATE_IRONMAN";
			case 3:
				return "HARDCORE_IRONMAN";
			case 4:
				return "GROUP_IRONMAN";
			case 5:
				return "HARDCORE_GROUP_IRONMAN";
			case 6:
				return "UNRANKED_GROUP_IRONMAN";
			default:
				return "NORMAL";
		}
	}

	private void writeFile(ExportData data, String trigger)
	{
		final File dir = new File(RuneLite.RUNELITE_DIR, "ca-roulette");
		if (!dir.isDirectory() && !dir.mkdirs())
		{
			log.warn("CA Roulette Export: could not create {}", dir);
			status("Export failed: could not create output folder.");
			return;
		}

		final String fileName = data.username.toLowerCase().trim().replace(' ', '_')
			+ data.profileType + ".json";
		final File file = new File(dir, fileName);

		final Gson prettyGson = gson.newBuilder()
			.setPrettyPrinting()
			.disableHtmlEscaping()
			.serializeNulls()
			.create();

		try (BufferedWriter writer = new BufferedWriter(
			new OutputStreamWriter(new FileOutputStream(file), StandardCharsets.UTF_8)))
		{
			prettyGson.toJson(data, writer);
		}
		catch (IOException e)
		{
			log.warn("CA Roulette Export: could not write {}", file, e);
			status("Export failed: " + e.getMessage());
			return;
		}

		log.info("CA Roulette Export ({}): wrote {} ({} CA tasks, {} completed)",
			trigger, file, data.combatAchievements.tasksTotal, data.combatAchievements.tasksCompleted);

		final String summary = data.combatAchievements.tasksCompleted + "/" + data.combatAchievements.tasksTotal
			+ " CA tasks, " + data.combatAchievements.pointsEarned + " pts";
		if (panel != null)
		{
			panel.setStatus("Exported " + summary + " -> " + fileName);
		}

		if (config.printFilePath())
		{
			final String msg = new ChatMessageBuilder()
				.append("[CA Roulette] Exported ")
				.append(summary)
				.append(" to ")
				.append(file.getAbsolutePath().replace('\\', '/'))
				.build();
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(msg)
				.build());
		}
	}

	private void status(String message)
	{
		log.info("CA Roulette Export: {}", message);
		if (panel != null)
		{
			panel.setStatus(message);
		}
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(new ChatMessageBuilder().append("[CA Roulette] " + message).build())
				.build());
		}
	}
}

