package com.caroulette.export;

import java.util.List;
import java.util.Map;

/**
 * Shape of the JSON file written to {@code .runelite/ca-roulette/<username>.json}.
 * Consumed by the CA Roulette website. Keep {@link #schemaVersion} in sync with
 * the website's importer when fields change.
 */
class ExportData
{
	static final int SCHEMA_VERSION = 2;

	int schemaVersion = SCHEMA_VERSION;
	String generatedAt;          // ISO-8601 UTC
	String username;
	String displayName;
	String accountType;          // NORMAL, IRONMAN, HARDCORE_IRONMAN, ULTIMATE_IRONMAN, GROUP_IRONMAN, ...
	String profileType;          // "", "-BETA", "-LEAGUES-4", ... (RuneScapeProfileType)
	int combatLevel;

	Map<String, Integer> skills;         // real (un-boosted) levels, e.g. {"Attack": 99}
	Map<String, String> quests;          // {"Dragon Slayer II": "FINISHED" | "IN_PROGRESS" | "NOT_STARTED"}
	List<String> questsFinished;         // convenience: names with state FINISHED

	CombatAchievements combatAchievements;
	Items items;

	static class CombatAchievements
	{
		int pointsEarned;                        // computed from completed tasks
		int pointsTotal;                         // computed from all tasks
		Map<String, Integer> tasksCompletedByTier;   // {"Easy": 33, ...}
		Map<String, Integer> tasksTotalByTier;
		int tasksCompleted;
		int tasksTotal;
		List<Task> tasks;
		List<Integer> completedIds;
		List<Integer> incompleteIds;
	}

	static class Task
	{
		int id;                  // struct param 1306 - stable task id
		String name;             // struct param 1308
		String description;      // struct param 1309 (null unless includeDescriptions)
		String tier;             // Easy .. Grandmaster
		int points;              // 1..6 by tier
		boolean completed;
	}

	static class Items
	{
		boolean bankIncluded;
		String note;             // set when a container could not be captured; null otherwise
		List<Item> equipment;
		List<Item> inventory;
		List<Item> bank;
	}

	static class Item
	{
		int id;
		String name;
		int quantity;

		Item(int id, String name, int quantity)
		{
			this.id = id;
			this.name = name;
			this.quantity = quantity;
		}
	}
}

